// máscara para números
function mascaraCampoNumerico(obj) {
	obj.value = obj.value.replace(/\D/g, '');
} 
  
// máscara para mês e ano
function mascaraCampoMesAno(obj) {
	mascaraCampoNumerico(obj);
	if (obj.value.length > 2)
		obj.value = obj.value.substr(0, 2) + '/' + obj.value.substr(2);
}

// calendário para selecionar diário
$(function() {
	
	var data = $("#data").val();
	
    $("#calendarioBusca").datepicker({
        dateFormat: 'yymmdd',
		defaultDate: data,
        dayNames: ['Domingo','Segunda','Terça','Quarta','Quinta','Sexta','Sábado','Domingo'],
        dayNamesMin: ['D','S','T','Q','Q','S','S','D'],
        dayNamesShort: ['Dom','Seg','Ter','Qua','Qui','Sex','Sáb','Dom'],
        monthNames: ['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'],
        monthNamesShort: ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'],
        onSelect: function (dateText, inst) {
    		selecaoDataNoCalendario(dateText);
    	}
    });
});

/**
 * Quando uma data é selecionada no calendário
 * @param dataTexto
 */
function selecaoDataNoCalendario(dataTexto) {
	var form = document.forms['buscaPorData'];
	form.data.value = dataTexto;
	form.submit();
}

/**
 * Navega entre as páginas da busca de palavras-chave 
 * @param pagina
 */
function vaiParaPaginaBusca(pagina) {
	var form = document.forms['buscaPorPalavra'];
	form.paginaIni.value = pagina;
	form.submit();
}

/* Ativa ou desativa id, coloando uma classe ativo */
function ativarDesativarId(ativar, id) {
	  var obj = document.getElementById(id);
	  var classe = (ativar) ? 'ativo' : '';
	  obj.className = classe;
}

/* Ao alterar a opção de busca por palavra-chave */
function selecaoOpcaoBusca(valor) {
	  var form = document.forms['buscaPorPalavra'];
	  form.palavraTipo.value = valor;
	  // vai para a página 0, pois pode pelo critério, muda a quantidade de resultados
	  form.paginaIni.value = 0;
	  form.submit();
}

